# Homebrew formula for Helium Agent. Generated by scripts/release-helium.sh; do not edit by hand.
#
#   export HOMEBREW_GITHUB_API_TOKEN="$(gh auth token)"
#   brew install nace-ai/tap/helium
class Helium < Formula
  desc "Coding agent harness tuned for small language models"
  homepage "https://github.com/nace-ai/helium-agent"
  version "1.4.1"
  license "MIT"

  # Release assets of the private repository download through the GitHub API.
  # Homebrew hands formulae only HOMEBREW_* variables, hence HOMEBREW_GITHUB_API_TOKEN.
  GITHUB_ASSET_HEADERS = [
    "Accept: application/octet-stream",
    *("Authorization: Bearer #{ENV.fetch("HOMEBREW_GITHUB_API_TOKEN")}" if ENV["HOMEBREW_GITHUB_API_TOKEN"]),
  ].freeze

  on_macos do
    on_arm do
      url "https://api.github.com/repos/nace-ai/helium-agent/releases/assets/705848127",
          headers: GITHUB_ASSET_HEADERS
      sha256 "5a64b77952a1bac36c29c1ff8bf3c1e143421760c126fd62125065677f946780"
    end

    on_intel do
      url "https://api.github.com/repos/nace-ai/helium-agent/releases/assets/705848117",
          headers: GITHUB_ASSET_HEADERS
      sha256 "7401596a2260a63dc2f6aba820da8c176da1ac9b83c2414c8b43ff5dec1ef95d"
    end
  end

  on_linux do
    on_arm do
      url "https://api.github.com/repos/nace-ai/helium-agent/releases/assets/705848123",
          headers: GITHUB_ASSET_HEADERS
      sha256 "3f1d68441b5e86c74192ff6d87e1cb31b0495652c26d18ba6a454092d2367464"
    end

    on_intel do
      url "https://api.github.com/repos/nace-ai/helium-agent/releases/assets/705848103",
          headers: GITHUB_ASSET_HEADERS
      sha256 "ac02b38f989bb61fd3eb77b176db3c559fd7375fd78225e9ccbbd197f67f8fdf"
    end
  end

  def install
    # The binary finds its themes, docs and native helpers next to itself;
    # Bun resolves the bin symlink to libexec.
    libexec.install Dir["*"]
    bin.install_symlink libexec/"helium"
  end

  test do
    assert_match(/\d+\.\d+\.\d+/, shell_output("#{bin}/helium --version"))
  end
end
